const { release_id: releaseId, production_host: productionHost } = $input.first().json;
const releaseIdPattern = /^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{6}Z(?:-[a-z0-9][a-z0-9-]*)?$/;
const hostPattern = /^[A-Za-z0-9.-]+$/;
if (typeof releaseId !== 'string' || !releaseIdPattern.test(releaseId)) {
  throw new Error('Set release_id to an approved UTC release directory name before running.');
}
if (typeof productionHost !== 'string' || !hostPattern.test(productionHost)) {
  throw new Error('Set production_host to the verified production VPS host name or address before running.');
}
return [{ json: { release_id: releaseId, production_host: productionHost } }];
